"use strict";(self.webpackChunkuniplus_developers=self.webpackChunkuniplus_developers||[]).push([["53811"],{1010(e){e.exports=JSON.parse('{"registro":{"codigo":"uniplus.cursor.invalido","status":400,"titulo":"Cursor de pagina\xe7\xe3o inv\xe1lido"},"descricao":{"codigo":"uniplus.cursor.invalido","requisitos":[],"oQueAconteceu":["O **cursor** informado no par\xe2metro `cursor` da listagem paginada \xe9 inv\xe1lido.","O cursor \xe9 opaco por design: um valor cifrado que carrega, entre outros\\ndados, o identificador do \xfaltimo item visto na p\xe1gina e uma\\netiqueta que identifica a que cole\xe7\xe3o ele pertence. O servidor nunca espera\\nque o cliente monte ou interprete esse valor \u2014 ele s\xf3 o devolve intacto,\\ncomo recebeu na p\xe1gina anterior, para pedir a pr\xf3xima.","Esta causa cobre qualquer motivo pelo qual o cursor n\xe3o \xe9 aceit\xe1vel nesta\\nrequisi\xe7\xe3o, deliberadamente sem distinguir qual: cifra corrompida ou\\nadulterada, etiqueta de recurso que n\xe3o corresponde \xe0 cole\xe7\xe3o sendo\\npercorrida (um cursor emitido para editais n\xe3o decodifica como cursor de\\ninscri\xe7\xf5es), dire\xe7\xe3o (`next`/`prev`) diferente da que o cursor foi emitido, ou\\n\u2014 em cole\xe7\xf5es vinculadas ao usu\xe1rio autenticado \u2014 um cursor sem v\xednculo de\\nusu\xe1rio, vinculado a outro usu\xe1rio, ou usado por requisi\xe7\xe3o an\xf4nima. Separar\\nesses motivos em causas distintas vazaria informa\xe7\xe3o a quem tenta adulterar um\\ncursor: \\"cursor existe mas \xe9 de outro usu\xe1rio\\" responde a uma pergunta que um\\natacante n\xe3o deveria conseguir fazer."],"comoResolver":["N\xe3o construa nem edite um cursor manualmente. Use sempre o valor exatamente\\ncomo o servidor o devolveu na resposta anterior (`next`/`prev` no header\\n`Link`), na mesma dire\xe7\xe3o em que foi emitido e para a mesma listagem.","Se o cursor \xe9 antigo, ele pode ter expirado em vez de estar inv\xe1lido \u2014 nesse\\ncaso a causa \xe9 distinta: veja\\n[cursor expirado](/erros/uniplus.cursor.expirado). Se o problema n\xe3o \xe9 o\\ncursor em si, mas o par\xe2metro de dire\xe7\xe3o, veja\\n[dire\xe7\xe3o de pagina\xe7\xe3o inv\xe1lida](/erros/uniplus.cursor.direcao_invalida)."],"ondeAparece":["Listagem paginada por cursor, quando o par\xe2metro cursor est\xe1 presente"]},"modulo":{"id":"transversais","nome":"Erros transversais","assunto":"Cursor"},"origem":{"repositorio":"unifesspa-edu-br/uniplus-api","commit":"bac0ecb24f352b6341ba53a00922b6237dd7a678"}}')}}]);